export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, apT = u / g, apH = u * u / (2 * g);
  const t = sdk.clamp(time, 0, T);
  const h = u * t - g * t * t / 2;
  const v = u - g * t;
  const F = m * g;
  let st;
  if (t <= 0) st = 'Ready to toss';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (Math.abs(t - apT) < 0.005) st = 'At the top';
  else if (t < apT) st = 'Rising'; else st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 300, h: 370, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 34, w: 300, h: 370, title: 'Velocity over time', state: '' }));
  const y0 = 370, sc = 270 / 2.2;
  o.push(sdk.axis('axis.h', { x: 70, y: y0, length: 270, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  const by = y0 - h * sc;
  o.push(sdk.circle('ball.toss', 140, by, 26));
  o.push(...sdk.vector('vec.v', { x: 140, y: by }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: 170, y: by }, { value: -g, direction: 'up' }, { scale: 4, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(190, 100, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = [];
  for (let i = 0; i <= 20; i++) { const tt = 1.8 * i / 20; pts.push({ x: tt, y: sdk.clamp(u - g * tt, -5.5, 5.5) }); }
  const cur = [];
  const n = 12;
  for (let i = 0; i <= n; i++) { const tt = t * i / n; cur.push({ x: tt, y: u - g * tt }); }
  const sl = [];
  for (let i = 0; i <= 1; i++) { const tt = sdk.clamp(t - 0.15 + 0.3 * i, 0, 1.8); sl.push({ x: tt, y: sdk.clamp(v + (-g) * (tt - t), -5.5, 5.5) }); }
  o.push(sdk.plot('plot.vt', { x: 340, y: 60, w: 285, h: 330, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v = u - g t', kind: 'line', points: pts }, { label: 'so far', kind: 'line', points: cur }, { label: 'slope a = -g', kind: 'line', points: sl }] }));
  o.push(sdk.text('plot.vt.note', 480, 50, 'slope a = -g', { role: 'warning' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] },
    quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: apT, apexHeight: apH, height: h, velocity: v, acceleration: -g, force: F } };
}
